const fs = require('fs');

function main() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim();
    const a = input.split('');
    const m = a.length;
    let count = 0;
    let t = 0;

    for (let i = 0; i < m && m !== 1; i++) {
        if (a[i].charCodeAt(0) <= 92) {
            count++;
        }
    }

    for (let i = 1; i < m; i++) {
        if (a[0].charCodeAt(0) > 92) {
            if (a[i].charCodeAt(0) <= 92) {
                t++;
            }
        }
    }

    if (m === 1) {
        const code = a[0].charCodeAt(0);
        if (code <= 92) {
            a[0] = String.fromCharCode(code + 32);
        } else {
            a[0] = String.fromCharCode(code - 32);
        }
    } else if (count === m) {
        for (let i = 0; i < m; i++) {
            a[i] = String.fromCharCode(a[i].charCodeAt(0) + 32);
        }
    } else if (t === m - 1) {
        a[0] = String.fromCharCode(a[0].charCodeAt(0) - 32);
        for (let i = 1; i < m; i++) {
            a[i] = String.fromCharCode(a[i].charCodeAt(0) + 32);
        }
    }

    process.stdout.write(a.join(''));
}

